import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Rules:
    - Each line is split on its first `=`; the name and value are both
      stripped of surrounding whitespace. Later `=` characters stay in the value.
    - Blank lines, lines starting with `#` (after stripping), and lines
      without `=` are ignored.
    - Key matching is exact and case-sensitive.
    - If the key appears more than once, the last occurrence wins.
    - Returns "" when the key is absent. A key present with an empty value
      also returns "".
    - Never reads files; `text` is the only input.
    """
    result = ""
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            result = value.strip()
    return result


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2", "b") == "2"
    assert config_value("a=1\nb=2", "a") == "1"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_is_stripped() -> None:
    assert config_value("  name  =  value with spaces  \n", "name") == "value with spaces"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b", "url") == "http://x/?a=b"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=1\n\n   \n  # b=2\nc=3"
    assert config_value(text, "a") == ""
    assert config_value(text, "b") == ""
    assert config_value(text, "c") == "3"


def test_lines_without_equals_ignored() -> None:
    assert config_value("junk\na=1", "junk") == ""
    assert config_value("junk\na=1", "a") == "1"


def test_duplicate_key_last_wins() -> None:
    assert config_value("a=1\na=2", "a") == "2"


def test_key_is_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_key_must_match_exactly() -> None:
    assert config_value("abc=1", "ab") == ""
    assert config_value("ab=1", "abc") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("a=1", "a", "1"),
        ("=1", "", "1"),
        ("a=1", "", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected

